// Oracle differential compare. See state_diff.hpp for the policy.
#include "state_diff.hpp"

#include <cstdio>
#include <string>
#include <string_view>

namespace andes_sim {

namespace {

void cmp(DiffReport& r, const std::string& field, unsigned long long ref,
         unsigned long long got) {
  ++r.compared;
  if (ref != got) r.diffs.push_back({field, ref, got});
}

}  // namespace

DiffReport diff_states(const hybrid_state_v1& ref, const hybrid_state_v1& got) {
  DiffReport r;

  cmp(r, "magic", ref.magic, got.magic);
  cmp(r, "version", ref.version, got.version);
  cmp(r, "flags", ref.flags, got.flags);
  cmp(r, "hart_id", ref.hart_id, got.hart_id);
  cmp(r, "priv", ref.priv, got.priv);
  cmp(r, "pc", ref.pc, got.pc);

  // mepc/mcause: in the trap-free hybrid ROI they round-trip (L24: restored at
  // resume, re-read at drain). mtval/mstatus stay out of scope where they are
  // implementation-defined / carry dirty bits (false positives).
  cmp(r, "mepc", ref.mepc, got.mepc);
  cmp(r, "mcause", ref.mcause, got.mcause);

  // Round-trip M-mode CSRs: mscratch (L23) and mtval/mie (L24) are restored at
  // resume and re-read at drain, so a trap-free ROI must match the oracle on
  // them. mip is excluded: its pending bits are hardware/platform-driven
  // (timer/external) and diverge between QEMU's functional clock and vsim's
  // cycle clock even with no trap (it still round-trips into the drained
  // record, just not the verifier).
  cmp(r, "mscratch", ref.mscratch, got.mscratch);
  cmp(r, "mtval", ref.mtval, got.mtval);
  cmp(r, "mie", ref.mie, got.mie);

  for (int i = 0; i < 32; ++i)
    cmp(r, "x" + std::to_string(i), ref.gpr[i], got.gpr[i]);

  if (ref.flags & HYBRID_FLAG_FP) {
    for (int i = 0; i < 32; ++i)
      cmp(r, "f" + std::to_string(i), ref.fpr[i], got.fpr[i]);
    cmp(r, "fcsr", ref.fcsr, got.fcsr);  // L20: frm + sticky fflags
  }

  if (ref.flags & HYBRID_FLAG_V) {
    cmp(r, "vstart", ref.vstart, got.vstart);
    cmp(r, "vtype", ref.vtype, got.vtype);
    cmp(r, "vl", ref.vl, got.vl);
    cmp(r, "vlenb", ref.vlenb, got.vlenb);
    cmp(r, "vxsat", ref.vxsat, got.vxsat);
    cmp(r, "vxrm", ref.vxrm, got.vxrm);
    cmp(r, "vcsr", ref.vcsr, got.vcsr);

    // One compared "field" per vector register; report the first differing
    // byte as "v<i>[<byte>]".
    for (int i = 0; i < 32; ++i) {
      ++r.compared;
      const uint8_t* a = &ref.vreg[static_cast<size_t>(i) * HYBRID_VLEN_BYTES_MAX];
      const uint8_t* b = &got.vreg[static_cast<size_t>(i) * HYBRID_VLEN_BYTES_MAX];
      for (int j = 0; j < HYBRID_VLEN_BYTES_MAX; ++j) {
        if (a[j] != b[j]) {
          r.diffs.push_back({"v" + std::to_string(i) + "[" +
                                 std::to_string(j) + "]",
                             a[j], b[j]});
          break;
        }
      }
    }
  }

  // Andes V5 CSR block (v3): the boot-static memory-system/extension CSRs plus
  // the DSP overflow flag round-trip through the trap-free ROI (ResumeDriver
  // restores them, StateDrain re-reads them), so a correct transport matches the
  // oracle. The X-macro is the single source of truth shared with the plugin
  // drain / resume / drain re-read, so this list can never drift out of sync.
  //
  // Exclusion: msp_bound/msp_base are the HW stack-protection bound registers.
  // QEMU resets them to all-ones; a vsim core that does not implement HW stack
  // protection drains 0. That divergence is an engine-implementation artifact,
  // not a transport bug (the restore is a tolerant no-op on a core lacking the
  // CSR) -- so they are transported but excluded from strict verify, exactly
  // like mip's hardware-driven pending bits.
  auto andes_verify_excluded = [](std::string_view name) {
    return name == "msp_bound" || name == "msp_base";
  };
  if (ref.flags & HYBRID_FLAG_ANDES) {
#define X(field, addr, name) \
  if (!andes_verify_excluded(name)) cmp(r, name, ref.andes.field, got.andes.field);
    HYBRID_ANDES_CSR_LIST(X)
#undef X
    for (int i = 0; i < HYBRID_PMA_CFG_NUM; ++i)
      cmp(r, "pmacfg" + std::to_string(i), ref.andes.pmacfg[i],
          got.andes.pmacfg[i]);
    for (int i = 0; i < HYBRID_PMA_ADDR_NUM; ++i)
      cmp(r, "pmaaddr" + std::to_string(i), ref.andes.pmaaddr[i],
          got.andes.pmaaddr[i]);
  }

  return r;
}

void print_diff_report(const DiffReport& r) {
  for (const FieldDiff& d : r.diffs)
    std::printf("[state-diff] %s: ref=0x%llx got=0x%llx\n", d.field.c_str(),
                d.ref, d.got);
  if (r.ok()) {
    std::printf(
        "[state-diff] PASS: %d fields match (counters and passthrough CSRs "
        "excluded)\n",
        r.compared);
  } else {
    std::printf("[state-diff] FAIL: %zu mismatch(es) (%d fields compared)\n",
                r.diffs.size(), r.compared);
  }
}

}  // namespace andes_sim

// Wire contract between the QEMU TCG plugin and vsim. Both sides write/read
// `struct hybrid_state_v1` byte-for-byte through a shared file.
//
// Stability: never repurpose offsets within a published version. Add new
// fields by consuming bytes from `reserved`, or by introducing v2 alongside.
//
// Endianness: multi-byte fields are little-endian (native on RV64 + x86-64
// host). The format is not endian-portable; cross-endian use would need an
// explicit byte-swap path.
//
// C and C++ both compile this header.

#ifndef HYBRID_STATE_ABI_H
#define HYBRID_STATE_ABI_H

#include <stdint.h>
#include <stddef.h>

#ifdef __cplusplus
extern "C" {
#endif

#define HYBRID_STATE_MAGIC   0x42594841u  // 'AHYB' little-endian
// Version 3 (Andes F0): append struct hybrid_andes_csr after mmisc_ctl, which
// grows the struct. Version 2 (L11) widened vreg[] to 128 bytes/register.
// Readers reject older files loudly (all three consumers check magic + version
// + size) instead of mis-parsing them.
#define HYBRID_STATE_VERSION 3u

#define HYBRID_FLAG_RV64  (1u << 0)
#define HYBRID_FLAG_FP    (1u << 1)
#define HYBRID_FLAG_V     (1u << 2)
// v3: the struct hybrid_andes_csr block carries live values (the producer ran
// on an Andes core that implements at least one of those CSRs). Clear means the
// block is all-zero and consumers skip restore/re-read/compare of it.
#define HYBRID_FLAG_ANDES (1u << 3)

// VLEN upper bound, in bytes: 128 covers the supported engine range
// VLEN 128..1024 (L11; also QEMU's RV_VLEN_MAX). This is the wire-format
// span per vector register; the LIVE width is the runtime `vlenb` field
// below, so one struct layout serves every engine config and the legs
// never disagree on offsets. A producer whose vlenb exceeds this ceiling
// must refuse to drain (see hybrid_v_drain_policy) rather than truncate.
#define HYBRID_VLEN_BYTES_MAX 128

// L26: bytes reserved for the V-register transport scratch page -- 32 vector
// registers at the wire-format span. The driver maps this many bytes ABOVE
// the program's --mem-size (so the scratch sits past the program's RAM), and
// vsim's v_scratch_gpa() / kVScratchBytes use the same count. Shared here so
// the producer (driver mmap sizing) and consumer (vsim sweep) never disagree.
#define HYBRID_V_SCRATCH_BYTES (32 * HYBRID_VLEN_BYTES_MAX)

// 64 PMP entries; pmpcfg slots reserved at 16 so the layout works for both
// RV64 (8 entries/CSR) and a future RV32 (4 entries/CSR) packing.
#define HYBRID_PMP_CFG_NUM  16
#define HYBRID_PMP_ADDR_NUM 64

// v3 Andes CSR block. PMA is 16 entries: pmacfg packs them at one byte each, so
// on RV64 only the even-numbered cfg CSRs exist -- 16 entries live in pmacfg0
// (0xBC0) + pmacfg2 (0xBC2), hence 2 cfg slots; 16 pmaaddr (0xBD0..0xBDF).
#define HYBRID_PMA_CFG_NUM  2
#define HYBRID_PMA_ADDR_NUM 16
#define HYBRID_PMA_CFG0_CSR   0xBC0
#define HYBRID_PMA_ADDR0_CSR  0xBD0

// Single source of truth for the SCALAR Andes CSRs transported in v3: X(field,
// csr_addr, gdb_name). Every consumer (QEMU plugin drain, ResumeDriver restore,
// StateDrain re-read, driver state_diff verify) iterates this list, so adding a
// CSR is one line here -- no consumer edits drift out of sync. PMA (arrays) is
// transported separately, mirroring the existing PMP loops. Each field is a
// 64-bit CSR value; 0 means the producing engine did not implement it (a
// tolerant no-op on restore). Order fixes the struct layout -- append only.
#define HYBRID_ANDES_CSR_LIST(X)            \
  X(mxstatus,       0x7C4, "mxstatus")      \
  X(mpft_ctl,       0x7C5, "mpft_ctl")      \
  X(mclk_ctl,       0x7DF, "mclk_ctl")      \
  X(milmb,          0x7C0, "milmb")         \
  X(mdlmb,          0x7C1, "mdlmb")         \
  X(mecc_code,      0x7C2, "mecc_code")     \
  X(mhsp_ctl,       0x7C6, "mhsp_ctl")      \
  X(msp_bound,      0x7C7, "msp_bound")     \
  X(msp_base,       0x7C8, "msp_base")      \
  X(mcountermask_m, 0x7D1, "mcountermask_m")\
  X(uitb,           0x800, "uitb")          \
  X(jvt,            0x017, "jvt")           \
  X(ucode,          0x801, "ucode")

// The Andes V5 machine/user CSRs a bare-metal Andes core sets up before the ROI
// (boot-static memory system + extension config) plus the DSP overflow flag.
// Restored at resume, re-read at drain, and verified -- live only when
// HYBRID_FLAG_ANDES is set. 13 scalar fields (above) + PMA = 31 * uint64_t.
struct hybrid_andes_csr {
#define HYBRID_ANDES_FIELD(field, addr, name) uint64_t field;
  HYBRID_ANDES_CSR_LIST(HYBRID_ANDES_FIELD)
#undef HYBRID_ANDES_FIELD
  uint64_t pmacfg[HYBRID_PMA_CFG_NUM];
  uint64_t pmaaddr[HYBRID_PMA_ADDR_NUM];
};

// All fields are naturally 8-byte aligned, so __attribute__((packed)) is
// unnecessary and would force unaligned access codegen. Layout is locked by
// the static_asserts in state_abi_check.h.
struct hybrid_state_v1 {
  uint32_t magic;
  uint32_t version;
  uint32_t flags;
  uint32_t hart_id;
  uint64_t pc;
  uint64_t priv;  // 0=U, 1=S, 3=M

  uint64_t gpr[32];
  uint64_t fpr[32];

  uint64_t mstatus;
  uint64_t mepc;
  uint64_t mtvec;
  uint64_t mcause;
  uint64_t mtval;
  uint64_t mscratch;
  uint64_t medeleg;
  uint64_t mideleg;
  uint64_t mip;
  uint64_t mie;
  uint64_t mcycle;
  uint64_t minstret;
  uint64_t satp;

  uint64_t pmpcfg[HYBRID_PMP_CFG_NUM];
  uint64_t pmpaddr[HYBRID_PMP_ADDR_NUM];

  uint64_t vstart;
  uint64_t vtype;
  uint64_t vl;
  uint64_t vlenb;
  uint8_t  vreg[32 * HYBRID_VLEN_BYTES_MAX];
  uint64_t vxsat;
  uint64_t vxrm;
  uint64_t vcsr;

  // L20: FP control/status -- frm[7:5] | fflags[4:0], live when
  // HYBRID_FLAG_FP is set. Drained by the plugin, restored by ResumeDriver,
  // re-read by StateDrain. Pre-L20 state files carry 0 here (reserved bytes
  // are written as zero), which reads back as the reset value (RNE, no
  // flags) -- exactly the old behavior, so no version bump.
  uint64_t fcsr;

  // Andes machine-setup CSRs: mcache_ctl (0x7CA) enables the L1 I/D caches,
  // mmisc_ctl (0x7D0) holds misc machine config. crt0 writes them once at
  // boot; transporting them keeps the cycle engine from resuming caches-off
  // (ResumeDriver has the full rationale). Drained by the plugin, restored by
  // ResumeDriver, but NOT re-read by StateDrain: they are boot-static and the
  // drained value is unused (no QEMU2 leg). Old state files carry 0 here
  // (reset value), which is the pre-existing behavior, so no version bump.
  uint64_t mcache_ctl;
  uint64_t mmisc_ctl;

  // v3: Andes V5 CSR block (live when HYBRID_FLAG_ANDES). 31 * 8 = 248 bytes.
  struct hybrid_andes_csr andes;

  uint8_t  reserved[64];  // zero-initialise on write; v3-compatible growth room
};

#ifdef __cplusplus
}  // extern "C"
#endif

#include "hybrid/state_abi_check.h"

#endif  // HYBRID_STATE_ABI_H

/* rt_c_fcsr.c - Round-trip fixture: fcsr (frm + sticky fflags) across the
 * handoff (L20).
 *
 * Phase 1 (QEMU1): set fcsr = 0x21 (frm=RTZ(1)<<5 | fflags=NX) right
 *   before the enter marker; the plugin drains it into
 *   hybrid_state_v1.fcsr (offset 5456, locked by state_abi_check.h).
 * Phase 2 (vsim): ResumeDriver must restore fcsr before the ROI runs.
 *   The in-ROI self-check reads it back; on mismatch the fixture exits 1
 *   immediately, so the vsim leg returns 1 instead of 200 and the harness
 *   fails loudly. On success it writes the distinct sentinel 0x45
 *   (frm=RDN(2)<<5 | fflags=NX|UF) for StateDrain to capture at the exit
 *   marker -- the drained file's fcsr field must read 0x45
 *   (tests/hybrid/e2e_fcsr_roundtrip.sh asserts both file values).
 *
 * crt0.S sets mstatus.FS=Initial, so fcsr is writable in M-mode on both
 * engines. The insns after the exit marker (main's epilogue) touch no FP
 * state, so the drain's 0-3 insn halt slack cannot disturb the sentinel.
 */
#include <stdlib.h>

#include "runtime/rt_c_helpers.h"

int main(void)
{
  /* Phase 1 (QEMU1): non-default rounding mode + a sticky flag. */
  unsigned long set = 0x21; /* frm=RTZ | fflags=NX */
  asm volatile("csrw fcsr, %0" ::"r"(set));

  enter_vsim();

  /* Phase 2 (vsim): the restored fcsr must be intact. */
  unsigned long got;
  asm volatile("csrr %0, fcsr" : "=r"(got));
  if (got != 0x21)
    exit(1);

  /* Leave a distinct value for the exit drain to capture. */
  unsigned long sentinel = 0x45; /* frm=RDN | fflags=NX|UF */
  asm volatile("csrw fcsr, %0" ::"r"(sentinel));

  exit_vsim();

  return 0;
}

/* rt_c_v_csrs.c - Round-trip fixture: V scalar CSR setup + drain
 * (2-phase: QEMU1 -> vsim).
 *
 * Configures vxsat, vxrm, vstart, vtype, and vl in the vsim ROI, then
 * drains -- exercising StateDrain's V-CSR capture path.
 *
 * Phase 1 (QEMU1): drain marker only (no V instructions; plugin PC
 *   drain constraint).
 * Phase 2 (vsim):  configure known V CSR values, then drain.
 *   - vsetvli: vl=8, vtype=e32/m1/ta/ma (0xD0)
 *   - csrw vxsat=1, vxrm=2, vstart=3 (vstart last: vsetvli resets it to 0)
 *
 * (The old phase-3 QEMU2 read-back + verify was removed with the QEMU2 leg;
 * the V CSRs now land in the drained hybrid_state_v1 only.)
 */
#include "runtime/rt_c_helpers.h"

int main(void)
{
  /* Phase 1 (QEMU1): no V instructions before the drain marker. */
  enter_vsim();

  /* Phase 2 (vsim): set known V CSR values.
   * crt0.S already set mstatus.VS=non-Off so vsetvli doesn't trap.
   * vstart must be written last: vsetvli resets vstart to 0. */
  asm volatile(
    "li     a0, 8\n"
    "vsetvli t0, a0, e32, m1, ta, ma\n"  /* vl=8, vtype=0xD0 */
    "li     t1, 1\n"
    "csrw   vxsat, t1\n"
    "li     t1, 2\n"
    "csrw   vxrm,  t1\n"
    "li     t1, 3\n"
    "csrw   vstart, t1\n"
    ::: "t0", "t1", "a0", "memory");

  exit_vsim();

  return 0;
}

// break_verify_diverge.S
//
// Bug: code inside the ROI that branches on (mcycle - minstret) will diverge
// between a hybrid run and the VERIFY=1 oracle.
//
// Mechanism:
//   vsim (RTL): counts actual clock cycles including pipeline stalls and cache
//               miss penalties.  For 1000 cache-striding loads:
//               mcycle_delta >> minstret_delta (stall cycles accumulate).
//   QEMU oracle: models CPI=1 for most instructions; mcycle_delta ≈ minstret_delta.
//
// The overhead = (mcycle_delta - minstret_delta) reliably separates the two:
//   QEMU oracle:  overhead ≈ 0  -> branch NOT taken -> a0 = 0xAAAA
//   vsim:         overhead >> 0 -> branch taken     -> a0 = 0xBBBB
//
// --verify then fires: "[state-diff] x10: ref=0xAAAA... got=0xBBBB..."
//
// The plain hybrid run always produces one fixed result (vsim is deterministic).
// Only --verify exposes the divergence.
//
// Scope: bare-metal, no async interrupts.

.section .text
.globl _start
_start:
    // Stash minstret and mcycle just before the ROI so we can compute deltas
    // inside the ROI (both are restored from QEMU1 drain = same baseline).
    csrr s0, minstret
    csrr s1, mcycle

    slti x0, x0, 0x5A0          // ENTER ROI
    // s0 = entry minstret, s1 = entry mcycle (restored from QEMU1 drain).

    // 1000 loads with 64-byte stride across the low 64 KB of DRAM.
    // Each load is a cold cache miss in vsim (L1 D-cache thrashing).
    // QEMU counts 1 cycle per instruction; vsim counts ~50+ stall cycles per miss.
    li   t0, 0                  // loop counter
    li   t1, 1000
    li   t2, 0                  // load address (starts at 0x00000000 = valid DRAM)
cache_stride_loop:
    lw   zero, 0(t2)            // cache-miss load; stalls vsim pipeline
    addi t2, t2, 64             // next cache line
    addi t0, t0, 1
    blt  t0, t1, cache_stride_loop

    csrr a0, mcycle
    csrr a1, minstret
    sub  a0, a0, s1             // mcycle_delta
    sub  a1, a1, s0             // minstret_delta
    sub  a0, a0, a1             // overhead = mcycle_delta - minstret_delta

    // QEMU oracle:  overhead ≈ 0 (CPI=1 model)
    // vsim:         overhead >> 0 (real cache-miss stall cycles)
    bnez a0, stalled
    li   a0, 0xAAAAAAAAAAAAAAAA  // oracle path: no stall overhead
    j    done
stalled:
    li   a0, 0xBBBBBBBBBBBBBBBB // hybrid path: stall cycles observed

done:
    slti x0, x0, 0x5A1          // EXIT ROI
    // --verify: oracle a0=0xAAAA, hybrid a0=0xBBBB -> FAIL

    li   t0, 0xe0080000
    sw   x0, 0(t0)
1:  j    1b

